<script>(()=>{const modals=[...document.querySelectorAll('.m-store-modal')],close=()=>modals.forEach(m=>m.hidden=true);document.querySelectorAll('[data-mobile-store-open]').forEach(b=>b.addEventListener('click',()=>{document.getElementById('mobile-store-offer-'+b.dataset.mobileStoreOpen).hidden=false;}));document.querySelectorAll('[data-mobile-store-close]').forEach(b=>b.addEventListener('click',close));modals.forEach(m=>m.addEventListener('click',e=>{if(e.target===m)close();}));document.addEventListener('keydown',e=>{if(e.key==='Escape')close();});})();</script>
